const recipients = $input.all();
const items = [];

for (const r of recipients) {
  const rJson = r.json;
  const urls = rJson.urls || [];

  if (urls.length === 0) {
    items.push({
      json: {
        url: "SKIP",
        recipientIndex: rJson.recipientIndex,
        name: rJson.name,
        email: rJson.email,
        extraPoints: rJson.extraPoints
      }
    });
  } else {
    for (const url of urls) {
      items.push({
        json: {
          url: url,
          recipientIndex: rJson.recipientIndex,
          name: rJson.name,
          email: rJson.email,
          extraPoints: rJson.extraPoints
        }
      });
    }
  }
}

return items;

// Parse HTML and preserve recipient metadata
const items = $input.all();

let splitItems = [];
try {
  splitItems = $('Split URLs').all();
} catch (e) {
  splitItems = [];
}

return items.map((item, index) => {
  const html = item.json.data || '';
  const sourceItem = (splitItems && splitItems[index]) ? splitItems[index].json : {};

  const url = item.json.url || sourceItem.url || 'SKIP';
  const recipientIndex = item.json.recipientIndex !== undefined ? item.json.recipientIndex : sourceItem.recipientIndex;
  const name = item.json.name || sourceItem.name || 'Valued Contact';
  const email = item.json.email || sourceItem.email || '';
  const extraPoints = item.json.extraPoints || sourceItem.extraPoints || '';

  const meta = { recipientIndex, name, email, extraPoints, url };

  if (url === 'SKIP') {
    return {
      json: {
        ...meta,
        title: 'No URL Provided',
        content: '',
        success: false
      }
    };
  }

  if (!html) {
    return {
      json: {
        ...meta,
        title: 'Error',
        content: 'Failed to fetch content',
        success: false
      }
    };
  }

  const titleMatch = html.match(/<title[^>]*>([^<]+)<\/title>/i);
  const h1Match = html.match(/<h1[^>]*>([^<]+)<\/h1>/i);
  const title = (titleMatch && titleMatch[1]) || (h1Match && h1Match[1]) || 'No title found';

  let cleanHtml = html.replace(/<script[^>]*>.*?<\/script>/gis, '');
  cleanHtml = cleanHtml.replace(/<style[^>]*>.*?<\/style>/gis, '');
  cleanHtml = cleanHtml.replace(/<nav[^>]*>.*?<\/nav>/gis, '');
  cleanHtml = cleanHtml.replace(/<header[^>]*>.*?<\/header>/gis, '');
  cleanHtml = cleanHtml.replace(/<footer[^>]*>.*?<\/footer>/gis, '');

  const paragraphs = [];
  const pRegex = /<p[^>]*>([^<]+(?:<[^/][^>]*>[^<]*<\/[^>]+>)*[^<]*)<\/p>/gi;
  let match;

  while ((match = pRegex.exec(cleanHtml)) !== null) {
    const text = match[1].replace(/<[^>]+>/g, '').trim();
    if (text.length > 20) {
      paragraphs.push(text);
    }
  }

  const headingRegex = /<h[1-6][^>]*>([^<]+)<\/h[1-6]>/gi;
  while ((match = headingRegex.exec(cleanHtml)) !== null) {
    const text = match[1].trim();
    if (text.length > 10) {
      paragraphs.push(text);
    }
  }

  let content = paragraphs.join('\n\n');
  content = content.replace(/\s+/g, ' ').trim();

  return {
    json: {
      ...meta,
      title: title.trim(),
      content: content || 'No content extracted',
      success: true
    }
  };
});

// Aggregate scraped content grouped by recipient
const items = $input.all();
const grouped = {};

for (const item of items) {
  const iJson = item.json;
  const idx = iJson.recipientIndex !== undefined ? iJson.recipientIndex : 0;

  if (!grouped[idx]) {
    grouped[idx] = {
      recipientIndex: idx,
      name: iJson.name || 'Valued Contact',
      email: iJson.email || '',
      talkingPoints: iJson.extraPoints || '',
      contents: [],
      urlCount: 0
    };
  }

  if (iJson.success && iJson.url !== 'SKIP') {
    grouped[idx].contents.push(`=== ${iJson.title} ===\nSource: ${iJson.url}\n\n${iJson.content}`);
    grouped[idx].urlCount++;
  }
}

return Object.values(grouped).map(g => ({
  json: {
    recipientIndex: g.recipientIndex,
    name: g.name,
    email: g.email,
    talkingPoints: g.talkingPoints,
    combinedContent: g.contents.length > 0 ? g.contents.join('\n\n---\n\n') : 'No web content scraped.',
    urlCount: g.urlCount
  }
}));

function sanitizeText(raw) {
  if (!raw || typeof raw !== 'string') return '';
  let str = raw;

  // 1. Fix common mojibake sequences
  str = str
    .replace(/\u00E2\u20AC\u2122|â€™/g, "'")
    .replace(/\u00E2\u20AC\u02DC|â€˜/g, "'")
    .replace(/\u00E2\u20AC\u0153|â€œ/g, '"')
    .replace(/\u00E2\u20AC\u009D|â€\u009D|â€ /g, '"')
    .replace(/\u00E2\u20AC\u2013|â€“/g, '-')
    .replace(/\u00E2\u20AC\u2014|â€”/g, '-')
    .replace(/\u00E2\u20AC\u00A6|â€¦/g, '...')
    .replace(/\u00C2\u00A0|Â\u00A0|Â /g, ' ')
    .replace(/Â/g, '');

  // 2. Normalize Unicode curly quotes / apostrophes to standard ASCII
  str = str
    .replace(/[\u2018\u2019\u201A\u201B\u02BC\u02BB\u00B4`]/g, "'")
    .replace(/[\u201C\u201D\u201E\u201F\u00AB\u00BB]/g, '"');

  // 3. Normalize Unicode dashes / hyphens to standard ASCII hyphen (-)
  str = str.replace(/[\u2010\u2011\u2012\u2013\u2014\u2015\u2212]/g, '-');

  // 4. Normalize Unicode ellipses
  str = str.replace(/\u2026/g, '...');

  // 5. Normalize non-breaking and special Unicode spaces to standard space
  str = str.replace(/[\u00A0\u1680\u2000-\u200A\u202F\u205F\u3000]/g, ' ');

  // 6. Strip invisible zero-width characters and BOM
  str = str.replace(/[\u200B-\u200D\uFEFF]/g, '');

  // 7. Normalize line endings and trim trailing line whitespace
  str = str
    .replace(/\r\n/g, '\n')
    .replace(/\r/g, '\n')
    .split('\n')
    .map(line => line.replace(/[ \t]+$/g, ''))
    .join('\n');

  // 8. Collapse excessive blank lines
  str = str.replace(/\n{3,}/g, '\n\n');

  return str.trim();
}

const items = $input.all();
let aggItems = [];
try {
  aggItems = $('Aggregate Content').all();
} catch (e) {
  aggItems = [];
}

return items.map((item, index) => {
  const meta = aggItems[index]?.json || {};
  const recipientName = meta.name || 'Valued Contact';
  const recipientEmail = meta.email || '';
  const recipientIndex = meta.recipientIndex !== undefined ? meta.recipientIndex : index;

  const rawText = item.json.text || '';
  const cleanRaw = sanitizeText(rawText);

  const subjectMatch = cleanRaw.match(/Subject:\s*(.+?)(?:\n|$)/i);
  const subject = subjectMatch ? sanitizeText(subjectMatch[1]) : 'Generated Email';

  let body = cleanRaw;
  if (subjectMatch) {
    body = cleanRaw.substring(cleanRaw.indexOf(subjectMatch[0]) + subjectMatch[0].length).trim();
  }
  body = sanitizeText(body);

  const fullText = `Subject: ${subject}\n\n${body}`;

  return {
    json: {
      recipientIndex,
      recipientName,
      recipientEmail,
      subject,
      body,
      fullEmail: fullText,
      success: true
    }
  };
});

function parseRelaxedJson(raw) {
  if (!raw || typeof raw !== 'string') return null;
  let text = raw.trim();
  try { return JSON.parse(text); } catch (e) {}
  text = text.replace(/(:\s*|\[\s*)(https?:\/\/[^\s,\]}]+)/g, '$1"$2"');
  try { return JSON.parse(text); } catch (e) {}
  text = text.replace(/([{,]\s*)([a-zA-Z0-9_$]+)\s*:/g, '$1"$2":');
  text = text.replace(/'([^'\\]*(?:\\.[^'\\]*)*)'/g, '"$1"');
  text = text.replace(/,\s*([}\]])/g, '$1');
  try { return JSON.parse(text); } catch (e) {}
  try {
    const fn = new Function('return (' + text + ');');
    return fn();
  } catch (e) {}
  return null;
}

const items = $input.all();
let rawRecipients = [];

// 1. Ingest items extracted from uploaded JSON file
for (const item of items) {
  if (item.json?.data) {
    if (Array.isArray(item.json.data)) {
      rawRecipients.push(...item.json.data);
    } else if (typeof item.json.data === 'object') {
      rawRecipients.push(item.json.data);
    }
  }
}

// 2. Ingest items from Webhook JSON payload or multipart form fields
if (rawRecipients.length === 0) {
  for (const item of items) {
    const body = item.json?.body || item.json;
    if (!body) continue;

    // A. Array under "recipients"
    if (Array.isArray(body.recipients) && body.recipients.length > 0) {
      rawRecipients.push(...body.recipients);
    }
    // B. Direct JSON array
    else if (Array.isArray(body) && body.length > 0) {
      rawRecipients.push(...body);
    }
    // C. Pasted JSON string under recipients or pastedJson
    else if (typeof body.recipients === 'string' && body.recipients.trim()) {
      const parsed = parseRelaxedJson(body.recipients);
      if (Array.isArray(parsed)) rawRecipients.push(...parsed);
      else if (parsed) rawRecipients.push(parsed);
    }
    // D. Single recipient entry
    else if (body.recipientEmail || body.email || body.recipientName || body.name) {
      rawRecipients.push({
        name: body.recipientName || body.name || 'Valued Contact',
        email: body.recipientEmail || body.email || '',
        urls: body.urls || [],
        extraPoints: body.extraPoints || body.talkingPoints || ''
      });
    }
  }
}

if (rawRecipients.length === 0) {
  throw new Error('No recipients found. Please provide recipient details via single entry or JSON file upload.');
}

// Normalize each recipient
return rawRecipients.map((r, index) => {
  let urls = [];
  const rawUrls = r.urls || r.links || r.url || r.link || [];
  if (Array.isArray(rawUrls)) {
    urls = rawUrls.map(u => String(u).trim()).filter(Boolean);
  } else if (typeof rawUrls === 'string') {
    urls = rawUrls.split('\n').map(u => u.trim()).filter(Boolean);
  }

  let extra = r.extraPoints || r.talkingPoints || '';
  if (Array.isArray(extra)) {
    extra = extra.map(e => String(e).trim()).filter(Boolean).join(', ');
  } else if (typeof extra !== 'string') {
    extra = String(extra || '');
  }

  return {
    json: {
      recipientIndex: index,
      name: r.name || 'Valued Contact',
      email: r.email || '',
      urls: urls,
      extraPoints: extra
    }
  };
});

const incoming = $input.item.json.body || $input.item.json;
const allEmails = $('Format Output').all();

// Retrieve recipientIndex from current Loop Over Emails or incoming payload
let idx = parseInt(incoming.recipientIndex, 10);
if (isNaN(idx)) {
  try {
    const loopItem = $('Loop Over Emails').item.json;
    idx = parseInt(loopItem.recipientIndex, 10);
  } catch (e) {}
}
if (isNaN(idx)) idx = 0;

const original = allEmails[idx]?.json || allEmails[0]?.json || {};

const subject = (incoming.Subject !== undefined && incoming.Subject !== null && incoming.Subject !== '')
  ? incoming.Subject
  : original.subject;

const body = (incoming['Email Body'] !== undefined && incoming['Email Body'] !== null && incoming['Email Body'] !== '')
  ? incoming['Email Body']
  : (incoming.body || original.body);

const recipientEmail = incoming.recipientEmail || original.recipientEmail;
const recipientName = incoming.recipientName || original.recipientName;

return [{
  json: {
    recipientIndex: idx,
    recipientName,
    recipientEmail,
    subject,
    body,
    fullEmail: `Subject: ${subject}\n\n${body}`,
    decision: incoming.Decision || incoming.decision || 'Approve',
    isEdited: (subject !== original.subject || body !== original.body)
  }
}];

const restored = $('Restore Current Email').first().json;
return [{
  json: {
    email: restored.recipientEmail,
    recipientName: restored.recipientName || 'Valued Contact',
    subject: restored.subject || 'Outreach Email',
    body: restored.body || '',
    status: 'sent',
    messageId: $json.id,
    sentAt: new Date().toISOString()
  }
}];

const items = $input.all();
const sentEmails = [];
const sentRecords = [];

// 1. Ingest from all loop iterations passed through $input.all()
for (const item of items) {
  const data = item.json || {};
  if (data.status === 'sent' && data.email) {
    if (!sentEmails.includes(data.email)) {
      sentEmails.push(data.email);
      sentRecords.push({
        email: data.email,
        recipientName: data.recipientName || '',
        subject: data.subject || '',
        messageId: data.messageId || '',
        sentAt: data.sentAt || ''
      });
    }
  }
}

// 2. Comprehensive fallback: scan all execution runs of Record Sent Email
try {
  let runIdx = 0;
  while (runIdx < 100) {
    try {
      const records = $('Record Sent Email', runIdx).all();
      if (!records || records.length === 0) break;
      for (const rec of records) {
        const j = rec.json || {};
        if (j.status === 'sent' && j.email && !sentEmails.includes(j.email)) {
          sentEmails.push(j.email);
          sentRecords.push({
            email: j.email,
            recipientName: j.recipientName || '',
            subject: j.subject || '',
            messageId: j.messageId || '',
            sentAt: j.sentAt || ''
          });
        }
      }
      runIdx++;
    } catch (e) {
      break;
    }
  }
} catch (e) {}

return [{
  json: {
    status: 'Completed',
    agentName: 'Kainoa',
    step: 'Sales Outreach Completed',
    sentEmails: sentEmails,
    sentRecords: sentRecords,
    jsonString: JSON.stringify(sentEmails, null, 2)
  }
}];

